def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.172.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.171.0"' not in init:
        sys.exit("ABORT: not at v3.171.0.")
    for k in ("variable_pay", "pay_reviews"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("PAY5", LESSONS_P5, QUESTIONS_P5, 9) + _validate("PAY6", LESSONS_P6, QUESTIONS_P6, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("PAY 5", LESSONS_P5, QUESTIONS_P5, "variable_pay",
         "Variable pay in ZhiftERP: the four rules and the component-carries-everything design; the Additional Salary doctype field by field — component, amount, payroll date, Overwrite Salary Structure Amount, recurring From/To dates, Deduct Full Tax on Selected Payroll Date; the overtime lane with approved-before-worked and the two control reads; bonuses with the list-drift check and the tax-timing policy; commissions from the system's own sales figures; agreed recoveries on self-terminating schedules; the Employee Advance lifecycle; and loan recovery from the slip with affordability at approval."),
        ("PAY 6", LESSONS_P6, QUESTIONS_P6, "pay_reviews",
         "Pay-change governance in ZhiftERP: the decision/execution split and the operator's procedural refusal; the approval matrix with the four-element evidence standard and the letter as anchor; same-day execution of the single change with preview and movement line; the arrears lane — honest From Dates, the sheet's arithmetic, the Arrears component entry, history standing; promotions via the Employee Promotion record with the silent-difference flag; the annual round's timetable, batch import, and both-ways verification; the movement record and the deciders' reads; and the boundary routing questions."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.171.0"', '"3.172.0"'))
    print("  data: PAYROLL 5 + 6 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.172.0")


if __name__ == "__main__":
    main()
